+void matmul(int n, const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C) {
+    // Zero C with memset for optimal performance
+    const size_t nn = static_cast<size_t>(n) * n;
+    std::memset(C, 0, nn * sizeof(float));
+
+    // i-k-j loop order: inner loop streams rows of B and C for better cache locality
+    // and enables compiler auto-vectorization with NEON FMA
+    #pragma clang loop vectorize(enable) unroll(full)
+    for (int i = 0; i < n; ++i) {
+        #pragma clang loop vectorize(enable) unroll(full)
+        for (int k = 0; k < n; ++k) {
+            float a = A[(size_t)i * n + k];
+            #pragma clang loop vectorize(enable) unroll(full)
+            for (int j = 0; j < n; ++j) {
+                C[(size_t)i * n + j] += a * B[(size_t)k * n + j];
+            }
         }
+    }
 }
 // OMEGA-BLOCK-END
